package cn.zhuatech.apautomation.deep;import cn.zhuatech.apautomation.model.AuditLog;import cn.zhuatech.apautomation.repository.AuditLogRepository;import jakarta.persistence.*;import jakarta.validation.*;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.math.*;import java.time.*;import java.util.*;
@Service @Transactional(readOnly=true) public class DeepDomainService{private final EntityManager em;private final AuditLogRepository audits;public DeepDomainService(EntityManager em,AuditLogRepository audits){this.em=em;this.audits=audits;}
 public ApDashboard dashboard(String org){List<InvoiceView> invoices=em.createQuery("select i from SupplierInvoice i where i.organizationCode=:o order by i.createdAt desc",SupplierInvoice.class).setParameter("o",org).getResultList().stream().map(this::view).toList();long exceptions=em.createQuery("select count(e) from MatchExceptionRecord e where e.status='OPEN' and e.invoiceId in(select i.id from SupplierInvoice i where i.organizationCode=:o)",Long.class).setParameter("o",org).getSingleResult();BigDecimal payable=invoices.stream().filter(i->!"PAID".equals(i.status())).map(InvoiceView::totalAmount).reduce(BigDecimal.ZERO,BigDecimal::add);return new ApDashboard(invoices,exceptions,payable);}
 @Transactional public PoLineView createPo(PoLineRequest r){PurchaseOrderLine p=new PurchaseOrderLine(r.organizationCode(),r.poNo(),r.lineNo(),r.vendorCode(),r.itemCode(),r.orderedQty(),r.unitPrice());em.persist(p);audit("PURCHASE_ORDER","登记订单行",r.poNo(),"line="+r.lineNo());return view(p);}
 @Transactional public PoLineView receive(Long id,ReceiptRequest r){PurchaseOrderLine p=po(id);BigDecimal next=p.receivedQty.add(r.quantity());if(next.compareTo(p.orderedQty)>0)throw conflict("累计收货数量不能超过订单数量");p.receivedQty=next;p.status=next.compareTo(p.orderedQty)==0?"RECEIVED":"PARTIAL";em.persist(new GoodsReceipt(id,r.receiptNo(),r.quantity(),r.receiptDate(),r.receiver()));audit("RECEIPT","确认收货",r.receiptNo(),p.poNo+"/"+p.lineNo);return view(p);}
 @Transactional public InvoiceView createInvoice(InvoiceRequest r){BigDecimal lineTotal=r.lines().stream().map(l->l.quantity().multiply(l.unitPrice())).reduce(BigDecimal.ZERO,BigDecimal::add);if(lineTotal.add(r.taxAmount()).compareTo(r.totalAmount())!=0)throw bad("发票行金额加税额必须等于发票总额");SupplierInvoice i=new SupplierInvoice(r.organizationCode(),r.vendorCode(),r.invoiceNo(),r.currency(),r.totalAmount(),r.taxAmount(),r.invoiceDate(),r.dueDate());em.persist(i);for(var l:r.lines())em.persist(new SupplierInvoiceLine(i.id,l.lineNo(),l.poNo(),l.poLineNo(),l.itemCode(),l.quantity(),l.unitPrice()));audit("INVOICE","登记发票",r.invoiceNo(),"amount="+r.totalAmount());return view(i);}
 @Transactional public MatchResult match(Long invoiceId,MatchRequest r){SupplierInvoice invoice=invoice(invoiceId);if(!"RECEIVED".equals(invoice.status)&&!"EXCEPTION".equals(invoice.status))throw conflict("当前发票不能执行匹配");em.createQuery("delete from MatchExceptionRecord e where e.invoiceId=:id and e.status='OPEN'").setParameter("id",invoiceId).executeUpdate();List<SupplierInvoiceLine> lines=em.createQuery("select l from SupplierInvoiceLine l where l.invoiceId=:id order by l.invoiceLineNo",SupplierInvoiceLine.class).setParameter("id",invoiceId).getResultList();List<ExceptionView> problems=new ArrayList<>();for(var l:lines){PurchaseOrderLine p=em.createQuery("select p from PurchaseOrderLine p where p.organizationCode=:o and p.poNo=:po and p.lineNo=:ln",PurchaseOrderLine.class).setParameter("o",invoice.organizationCode).setParameter("po",l.poNo).setParameter("ln",l.poLineNo).getResultStream().findFirst().orElse(null);if(p==null){problems.add(exception(invoice,l,"PO_NOT_FOUND","未找到采购订单行",l.lineAmount));continue;}if(!invoice.vendorCode.equals(p.vendorCode)){problems.add(exception(invoice,l,"VENDOR_MISMATCH","发票供应商与订单不一致",l.lineAmount));continue;}BigDecimal receivedValue=p.receivedQty.multiply(p.unitPrice),variance=l.lineAmount.subtract(receivedValue).abs(),tolerance=l.lineAmount.multiply(r.tolerancePercent()).divide(BigDecimal.valueOf(100),2,RoundingMode.HALF_UP);if(variance.compareTo(tolerance)>0)problems.add(exception(invoice,l,"AMOUNT_VARIANCE","发票金额超过收货金额容差",variance));}
  invoice.status=problems.isEmpty()?"MATCHED":"EXCEPTION";audit("THREE_WAY_MATCH","三单匹配",invoice.invoiceNo,invoice.status+" exceptions="+problems.size());return new MatchResult(invoice.status,lines.size(),problems.size(),problems);}
 @Transactional public InvoiceView approve(Long id){SupplierInvoice i=invoice(id);if(!"MATCHED".equals(i.status))throw conflict("只有三单匹配通过的发票可以批准");i.status="APPROVED";audit("APPROVAL","批准付款",i.invoiceNo,i.totalAmount.toString());return view(i);}
 @Transactional public PaymentView schedule(Long id,PaymentRequest r){SupplierInvoice i=invoice(id);if(!"APPROVED".equals(i.status))throw conflict("发票批准后才能生成付款计划");if(r.amount().compareTo(i.totalAmount)>0)throw bad("付款金额不能超过发票总额");PaymentPlan p=new PaymentPlan(id,r.paymentDate(),r.amount(),r.bankAccountMask());em.persist(p);i.status="SCHEDULED";audit("PAYMENT","生成付款计划",i.invoiceNo,r.paymentDate().toString());return view(p);}
 @Transactional public PaymentView pay(Long planId,PayRequest r){PaymentPlan p=em.find(PaymentPlan.class,planId);if(p==null)throw notFound("付款计划不存在");if(!"SCHEDULED".equals(p.status))throw conflict("付款计划不能重复执行");p.status="PAID";p.paymentReference=r.paymentReference();SupplierInvoice i=invoice(p.invoiceId);i.status="PAID";audit("PAYMENT","确认付款",i.invoiceNo,r.paymentReference());return view(p);}
 private ExceptionView exception(SupplierInvoice i,SupplierInvoiceLine l,String type,String desc,BigDecimal variance){MatchExceptionRecord e=new MatchExceptionRecord(i.id,l.id,type,desc,variance);em.persist(e);return new ExceptionView(e.id,type,desc,variance,e.status);}private PurchaseOrderLine po(Long id){PurchaseOrderLine p=em.find(PurchaseOrderLine.class,id);if(p==null)throw notFound("订单行不存在");return p;}private SupplierInvoice invoice(Long id){SupplierInvoice i=em.find(SupplierInvoice.class,id);if(i==null)throw notFound("发票不存在");return i;}private PoLineView view(PurchaseOrderLine p){return new PoLineView(p.id,p.organizationCode,p.poNo,p.lineNo,p.vendorCode,p.itemCode,p.orderedQty,p.receivedQty,p.unitPrice,p.status,p.version);}private InvoiceView view(SupplierInvoice i){return new InvoiceView(i.id,i.organizationCode,i.vendorCode,i.invoiceNo,i.currency,i.totalAmount,i.taxAmount,i.invoiceDate,i.dueDate,i.status,i.version);}private PaymentView view(PaymentPlan p){return new PaymentView(p.id,p.invoiceId,p.paymentDate,p.amount,p.bankAccountMask,p.status,p.paymentReference);}private void audit(String m,String a,String n,String d){audits.save(new AuditLog(m,a,n,"domain-service",d));}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);}private ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
 public record PoLineRequest(@NotBlank String organizationCode,@NotBlank String poNo,@Positive int lineNo,@NotBlank String vendorCode,@NotBlank String itemCode,@Positive BigDecimal orderedQty,@Positive BigDecimal unitPrice){}public record ReceiptRequest(@NotBlank String receiptNo,@Positive BigDecimal quantity,@NotNull LocalDate receiptDate,@NotBlank String receiver){}public record InvoiceLineRequest(@Positive int lineNo,@NotBlank String poNo,@Positive int poLineNo,@NotBlank String itemCode,@Positive BigDecimal quantity,@Positive BigDecimal unitPrice){}public record InvoiceRequest(@NotBlank String organizationCode,@NotBlank String vendorCode,@NotBlank String invoiceNo,@NotBlank String currency,@Positive BigDecimal totalAmount,@PositiveOrZero BigDecimal taxAmount,@NotNull LocalDate invoiceDate,@NotNull LocalDate dueDate,@NotEmpty @Valid List<InvoiceLineRequest> lines){}public record MatchRequest(@DecimalMin("0") @DecimalMax("10") BigDecimal tolerancePercent){}public record PaymentRequest(@NotNull LocalDate paymentDate,@Positive BigDecimal amount,@NotBlank String bankAccountMask){}public record PayRequest(@NotBlank String paymentReference){}
 public record PoLineView(Long id,String organizationCode,String poNo,int lineNo,String vendorCode,String itemCode,BigDecimal orderedQty,BigDecimal receivedQty,BigDecimal unitPrice,String status,long version){}public record InvoiceView(Long id,String organizationCode,String vendorCode,String invoiceNo,String currency,BigDecimal totalAmount,BigDecimal taxAmount,LocalDate invoiceDate,LocalDate dueDate,String status,long version){}public record ExceptionView(Long id,String type,String description,BigDecimal variance,String status){}public record MatchResult(String status,int lineCount,int exceptionCount,List<ExceptionView> exceptions){}public record PaymentView(Long id,Long invoiceId,LocalDate paymentDate,BigDecimal amount,String bankAccountMask,String status,String paymentReference){}public record ApDashboard(List<InvoiceView> invoices,long openExceptions,BigDecimal unpaidAmount){}
}
